import {createGardenState,stepGarden,restoreGardenState} from '../../../../src/js/garden/GardenSimulation.js';
import {gardenPilot} from './piloto.mjs';
let s=createGardenState('EASY'),lastSupport=null;for(let i=0;i<18000&&s.stage!=='COMPLETE';i++){if(s.player.support)lastSupport={...s.player,time:s.time};const before={...s.player,time:s.time};const ev=stepGarden(s,gardenPilot(s),1/120,'EASY');if(ev.some(e=>e.type==='fall'))console.log(JSON.stringify({before,lastSupport}));if(i===999)s=restoreGardenState(JSON.parse(JSON.stringify(s)),'EASY');}
